const startJobStep = `-- name: StartJobStep :one
INSERT INTO provisioning_job_steps (tenant_id, job_id, seq, name, status, attempt, started_at)
VALUES ($1, $2,
        (SELECT COALESCE(max(s.seq) + 1, 0) FROM provisioning_job_steps s WHERE s.job_id = $2),
        $3, 'running', 1, now())
ON CONFLICT (job_id, name) DO UPDATE
SET status = 'running', attempt = provisioning_job_steps.attempt + 1, started_at = now(), finished_at = NULL,
    error_code = NULL
WHERE provisioning_job_steps.status <> 'succeeded'
RETURNING id, tenant_id, job_id, seq, name, status, attempt, started_at, finished_at, error_code, detail, created_resources, compensation_status
`

type StartJobStepParams struct {
	TenantID *uuid.UUID
	JobID    uuid.UUID
	Name     string
}

// Bắt đầu hoặc chạy lại một step (seq = thứ tự xuất hiện đầu tiên). Step đã succeeded ⇒ 0 hàng: bỏ qua — /retry tiếp
// tục từ step lỗi (§11.3).
func (q *Queries) StartJobStep(ctx context.Context, arg StartJobStepParams) (ProvisioningJobStep, error) {
	row := q.db.QueryRow(ctx, startJobStep, arg.TenantID, arg.JobID, arg.Name)
	var i ProvisioningJobStep
	err := row.Scan(
		&i.ID,
		&i.TenantID,
		&i.JobID,
		&i.Seq,
		&i.Name,
		&i.Status,
		&i.Attempt,
		&i.StartedAt,
		&i.FinishedAt,
		&i.ErrorCode,
		&i.Detail,
		&i.CreatedResources,
		&i.CompensationStatus,
	)
	return i, err
}

const transitionJob = `-- name: TransitionJob :one
UPDATE provisioning_jobs
SET status        = $1::text,
    output        = COALESCE($2, output),
    error         = $3,
    resource_type = COALESCE($4, resource_type),
    resource_id   = COALESCE($5, resource_id),
    finished_at   = CASE WHEN $1::text IN ('succeeded', 'failed', 'cancelled', 'rolled_back') THEN now() END
WHERE id = $6 AND status = $7::text AND attempt = $8
RETURNING id, tenant_id, instance_id, kind, request_key, dedupe_key, lock_key, status, current_step, attempt, max_attempts, input, output, error, resource_type, resource_id, queue_job_id, requested_by, created_at, timeout_at, started_at, finished_at
`

type TransitionJobParams struct {
	ToStatus     string
	Output       []byte
	Error        []byte
	ResourceType *string
	ResourceID   *string
	ID           uuid.UUID
	FromStatus   string
	Attempt      int32
}

// Chuyển trạng thái có điều kiện theo (status, attempt) đã quan sát: worker kết thúc lượt chạy của chính nó, reaper thu
// hồi job — bên đến sau nhận 0 hàng. finished_at chỉ đặt ở trạng thái kết thúc.
func (q *Queries) TransitionJob(ctx context.Context, arg TransitionJobParams) (ProvisioningJob, error) {
	row := q.db.QueryRow(ctx, transitionJob,
		arg.ToStatus,
		arg.Output,
		arg.Error,
		arg.ResourceType,
		arg.ResourceID,
		arg.ID,
		arg.FromStatus,
		arg.Attempt,
	)
	var i ProvisioningJob
	err := row.Scan(
		&i.ID,
		&i.TenantID,
		&i.InstanceID,
		&i.Kind,
		&i.RequestKey,
		&i.DedupeKey,
		&i.LockKey,
		&i.Status,
		&i.CurrentStep,
		&i.Attempt,
		&i.MaxAttempts,
		&i.Input,
		&i.Output,
		&i.Error,
		&i.ResourceType,
		&i.ResourceID,
		&i.QueueJobID,
		&i.RequestedBy,
		&i.CreatedAt,
		&i.TimeoutAt,
		&i.StartedAt,
		&i.FinishedAt,
	)
	return i, err
}
